function validateInitializeResult(value) {
    if (!isObject(value) ||
        typeof value.protocolVersion !== "string" ||
        !isObject(value.capabilities) ||
        !isObject(value.serverInfo) ||
        typeof value.serverInfo.name !== "string" ||
        typeof value.serverInfo.version !== "string" ||
        (value.instructions !== undefined && typeof value.instructions !== "string")) {
        throw new McpError(JSON_RPC_ERROR_CODES.invalidRequest, "Invalid MCP initialize result");
    }
    return value;
}

function invalid(message) {
    return new McpError(JSON_RPC_ERROR_CODES.invalidRequest, message);
}

function validateListPage(method, key, value, isItem) {
    const items = isObject(value) ? value[key] : undefined;
    if (!isObject(value) || !Array.isArray(items))
        throw invalid(`Invalid MCP ${method} result`);
    for (const item of items) {
        if (!isObject(item) || !isItem(item))
            throw invalid(`Invalid entry in MCP ${method} result`);
    }
    // Some servers end pagination with `null` or `""` instead of omitting the cursor.
    const nextCursor = value.nextCursor === null || value.nextCursor === "" ? undefined : value.nextCursor;
    if (nextCursor !== undefined && typeof nextCursor !== "string")
        throw invalid(`Invalid MCP ${method} cursor`);
    return { items, ...(nextCursor === undefined ? {} : { nextCursor }) };
}

function toResource(item) {
    return { ...item, name: item.name ?? item.uri };
}

function toResourceTemplate(item) {
    return { ...item, name: item.name ?? item.uriTemplate };
}

function pageCursor(page) {
    return page.nextCursor === undefined ? {} : { nextCursor: page.nextCursor };
}

function validateReadResourceResult(value) {
    if (!isObject(value) || !Array.isArray(value.contents))
        throw invalid("Invalid MCP resources/read result");
    for (const contents of value.contents) {
        if (!isObject(contents) ||
            typeof contents.uri !== "string" ||
            (typeof contents.text !== "string" && typeof contents.blob !== "string")) {
            throw invalid("Invalid contents in MCP resources/read result");
        }
    }
    return value;
}

function validateCallToolResult(value) {
    if (!isObject(value) || (value.content !== undefined && !Array.isArray(value.content))) {
        throw new McpError(JSON_RPC_ERROR_CODES.invalidRequest, "Invalid MCP tools/call result");
    }
    return (value.content === undefined ? { ...value, content: [] } : value);
}

get connectionState() {
        return this.state;
    }

get serverInfo() {
        return this.serverInfoValue;
    }

get serverCapabilities() {
        return this.serverCapabilitiesValue;
    }

get instructions() {
        return this.instructionsValue;
    }

get protocolVersion() {
        return this.protocolVersionValue;
    }

async connect(transport) {
        if (this.state !== "idle")
            throw new Error(`Cannot connect MCP client in ${this.state} state`);
        this.state = "connecting";
        this.transport = transport;
        this.disposers = [
            transport.onMessage((message) => this.handleMessage(message)),
            // Transport errors are reported only. Pending requests fail when the transport closes.
            transport.onError((error) => this.emitError(error)),
            transport.onClose(() => this.handleTransportClose()),
        ];
        try {
            await transport.start();
            const capabilities = { ...this.options.capabilities };
            if (this.options.roots && capabilities.roots === undefined)
                capabilities.roots = {};
            const result = validateInitializeResult(await this.requestInternal("initialize", {
                protocolVersion: this.options.protocolVersion ?? LATEST_PROTOCOL_VERSION,
                capabilities,
                clientInfo: {
                    name: this.options.name,
                    version: this.options.version,
                    ...(this.options.title === undefined ? {} : { title: this.options.title }),
                },
            }, {}, true));
            if (!SUPPORTED_PROTOCOL_VERSIONS.includes(result.protocolVersion)) {
                throw new Error(`MCP server selected unsupported protocol version ${result.protocolVersion}`);
            }
            this.protocolVersionValue = result.protocolVersion;
            this.serverInfoValue = result.serverInfo;
            this.serverCapabilitiesValue = result.capabilities;
            this.instructionsValue = result.instructions;
            transport.setProtocolVersion?.(result.protocolVersion);
            await this.notifyInternal("notifications/initialized", undefined, true);
            this.state = "connected";
            return result;
        }
        catch (error) {
            await this.close().catch(() => { });
            throw error;
        }
    }

request(method, params, options = {}) {
        return this.requestInternal(method, params, options, false);
    }

notify(method, params) {
        return this.notifyInternal(method, params, false);
    }

setRequestHandler(method, handler) {
        this.requestHandlers.set(method, handler);
        return () => {
            if (this.requestHandlers.get(method) === handler)
                this.requestHandlers.delete(method);
        };
    }

onNotification(method, listener) {
        const listeners = this.notificationListeners.get(method) ?? new Set();
        this.notificationListeners.set(method, listeners);
        listeners.add(listener);
        return () => {
            listeners.delete(listener);
            if (listeners.size === 0)
                this.notificationListeners.delete(method);
        };
    }

onError(listener) {
        this.errorListeners.add(listener);
        return () => this.errorListeners.delete(listener);
    }

onClose(listener) {
        this.closeListeners.add(listener);
        return () => this.closeListeners.delete(listener);
    }

async ping(options = {}) {
        await this.request("ping", undefined, options);
    }

async listTools(options = {}) {
        return (await this.listAll("tools/list", "tools", isTool, options));
    }

async listResources(options = {}) {
        return (await this.listAll("resources/list", "resources", isResource, options)).map(toResource);
    }

async listResourcesPage(cursor, options = {}) {
        const page = await this.listPage("resources/list", "resources", isResource, cursor, options);
        return { resources: page.items.map(toResource), ...pageCursor(page) };
    }

async listResourceTemplates(options = {}) {
        const templates = await this.listAll("resources/templates/list", "resourceTemplates", isResourceTemplate, options);
        return templates.map(toResourceTemplate);
    }

async listResourceTemplatesPage(cursor, options = {}) {
        const page = await this.listPage("resources/templates/list", "resourceTemplates", isResourceTemplate, cursor, options);
        return { resourceTemplates: page.items.map(toResourceTemplate), ...pageCursor(page) };
    }

async readResource(uri, options = {}) {
        return validateReadResourceResult(await this.request("resources/read", { uri }, options));
    }

async listPage(method, key, isItem, cursor, options) {
        return validateListPage(method, key, await this.request(method, cursor === undefined ? undefined : { cursor }, options), isItem);
    }

async listAll(method, key, isItem, options) {
        const items = [];
        const cursors = new Set();
        let cursor;
        for (let pageNumber = 0; pageNumber < MAX_LIST_PAGES; pageNumber++) {
            const page = await this.listPage(method, key, isItem, cursor, options);
            items.push(...page.items);
            if (page.nextCursor === undefined)
                return items;
            if (cursors.has(page.nextCursor))
                throw new Error(`MCP ${method} returned duplicate cursor: ${page.nextCursor}`);
            cursors.add(page.nextCursor);
            cursor = page.nextCursor;
        }
        throw new Error(`MCP ${method} exceeded ${MAX_LIST_PAGES} pages`);
    }

async callTool(name, args, options = {}) {
        return validateCallToolResult(await this.request("tools/call", { name, ...(args === undefined ? {} : { arguments: args }) }, options));
    }

async close() {
        const transport = this.transport;
        this.transport = undefined;
        this.disposeTransportListeners();
        this.markClosed(new McpConnectionClosedError());
        await transport?.close();
    }

async requestInternal(method, params, options, allowConnecting) {
        const transport = this.requireTransport(allowConnecting);
        if (options.signal?.aborted)
            throw new McpAbortError();
        const id = this.nextRequestId++;
        const progressToken = options.onProgress ? id : undefined;
        const requestParams = progressToken === undefined
            ? params
            : { ...params, _meta: { ...(isObject(params?._meta) ? params._meta : {}), progressToken } };
        const message = {
            jsonrpc: "2.0",
            id,
            method,
            ...(requestParams === undefined ? {} : { params: requestParams }),
        };
        return new Promise((resolve, reject) => {
            const entry = {
                resolve,
                reject,
                timeoutMs: options.timeoutMs ?? this.options.requestTimeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS,
                timer: undefined,
                signal: options.signal,
                // The spec forbids cancelling `initialize`.
                onAbort: () => this.cancelPending(id, new McpAbortError(), method !== "initialize", String(options.signal?.reason ?? "Aborted")),
                sendController: new AbortController(),
                cancellable: method !== "initialize",
                onProgress: options.onProgress,
                progressToken,
            };
            this.pending.set(id, entry);
            if (progressToken !== undefined)
                this.progressRequests.set(progressToken, id);
            options.signal?.addEventListener("abort", entry.onAbort, { once: true });
            this.armTimeout(id, entry);
            transport
                .send(message, { signal: entry.sendController.signal })
                .catch((error) => this.cancelPending(id, error, false));
        });
    }

async notifyInternal(method, params, allowConnecting) {
        await this.requireTransport(allowConnecting).send({
            jsonrpc: "2.0",
            method,
            ...(params === undefined ? {} : { params }),
        });
    }

requireTransport(allowConnecting) {
        if (this.transport && (this.state === "connected" || (allowConnecting && this.state === "connecting"))) {
            return this.transport;
        }
        throw new McpConnectionClosedError(`MCP client is ${this.state}`);
    }

handleMessage(message) {
        if (isJsonRpcResponse(message)) {
            this.handleResponse(message);
            return;
        }
        if (isJsonRpcRequest(message)) {
            void this.handleRequest(message);
            return;
        }
        if (isJsonRpcNotification(message)) {
            this.handleNotification(message.method, message.params);
            return;
        }
        this.emitError(new McpError(JSON_RPC_ERROR_CODES.invalidRequest, "Received invalid JSON-RPC message"));
    }

handleResponse(message) {
        const entry = this.pending.get(message.id);
        if (!entry) {
            this.emitError(new Error(`Received response for unknown MCP request ${String(message.id)}`));
            return;
        }
        this.removePending(message.id, entry);
        if ("error" in message)
            entry.reject(new McpError(message.error.code, message.error.message, message.error.data));
        else
            entry.resolve(message.result);
    }

async handleRequest(message) {
        const transport = this.transport;
        if (!transport)
            return;
        const handler = this.requestHandlers.get(message.method);
        if (!handler) {
            await transport
                .send({
                jsonrpc: "2.0",
                id: message.id,
                error: { code: JSON_RPC_ERROR_CODES.methodNotFound, message: `Method not found: ${message.method}` },
            })
                .catch((error) => this.emitError(error));
            return;
        }
        const controller = new AbortController();
        this.incoming.set(message.id, controller);
        try {
            const result = await handler(message.params, { signal: controller.signal });
            await transport.send({ jsonrpc: "2.0", id: message.id, result: result ?? {} });
        }
        catch (error) {
            const responseError = error instanceof McpError
                ? { code: error.code, message: error.message, data: error.data }
                : { code: JSON_RPC_ERROR_CODES.internalError, message: toError(error).message };
            await transport
                .send({ jsonrpc: "2.0", id: message.id, error: responseError })
                .catch((sendError) => this.emitError(sendError));
        }
        finally {
            this.incoming.delete(message.id);
        }
    }

handleNotification(method, params) {
        if (method === "notifications/progress")
            this.handleProgress(params);
        else if (method === "notifications/cancelled")
            this.handleCancelled(params);
        for (const listener of this.notificationListeners.get(method) ?? []) {
            try {
                listener(params);
            }
            catch (error) {
                this.emitError(error);
            }
        }
    }

handleProgress(params) {
        if (!isObject(params) || !isJsonRpcId(params.progressToken) || typeof params.progress !== "number")
            return;
        const requestId = this.progressRequests.get(params.progressToken);
        const entry = requestId === undefined ? undefined : this.pending.get(requestId);
        if (requestId === undefined || !entry)
            return;
        this.armTimeout(requestId, entry);
        try {
            entry.onProgress?.(params);
        }
        catch (error) {
            this.emitError(error);
        }
    }

handleCancelled(params) {
        if (isObject(params) && isJsonRpcId(params.requestId))
            this.incoming.get(params.requestId)?.abort(params.reason);
    }

armTimeout(id, entry) {
        if (entry.timer)
            clearTimeout(entry.timer);
        if (!Number.isFinite(entry.timeoutMs) || entry.timeoutMs <= 0)
            return;
        entry.timer = setTimeout(() => {
            this.cancelPending(id, new McpTimeoutError(entry.timeoutMs), entry.cancellable, "Request timed out");
        }, entry.timeoutMs);
    }

cancelPending(id, error, notifyServer, reason) {
        const entry = this.pending.get(id);
        if (!entry)
            return;
        this.removePending(id, entry);
        entry.reject(error);
        if (notifyServer && this.transport) {
            void this.transport
                .send({
                jsonrpc: "2.0",
                method: "notifications/cancelled",
                params: { requestId: id, ...(reason ? { reason } : {}) },
            })
                .catch((sendError) => this.emitError(sendError));
        }
    }

removePending(id, entry) {
        this.pending.delete(id);
        if (entry.timer)
            clearTimeout(entry.timer);
        if (entry.progressToken !== undefined)
            this.progressRequests.delete(entry.progressToken);
        entry.signal?.removeEventListener("abort", entry.onAbort);
        entry.sendController.abort();
    }

rejectPending(error) {
        for (const [id, entry] of this.pending) {
            this.removePending(id, entry);
            entry.reject(error);
        }
    }

handleTransportClose() {
        this.markClosed(new McpConnectionClosedError());
    }

markClosed(error) {
        const wasClosed = this.state === "closed";
        this.state = "closed";
        this.rejectPending(error);
        for (const controller of this.incoming.values())
            controller.abort(error);
        this.incoming.clear();
        if (wasClosed)
            return;
        for (const listener of [...this.closeListeners]) {
            try {
                listener();
            }
            catch (listenerError) {
                this.emitError(listenerError);
            }
        }
    }

emitError(error) {
        const normalized = toError(error);
        for (const listener of this.errorListeners)
            listener(normalized);
    }

disposeTransportListeners() {
        for (const dispose of this.disposers.splice(0))
            dispose();
    }

function plainText(page) {
    if (page.ok)
        return "Authorization complete. You may close this window.";
    return page.details ? `${page.message}\n\n${page.details}` : page.message;
}

static async listen(options = {}) {
        const host = options.host ?? "127.0.0.1";
        const redirectHost = options.redirectHost ?? host;
        const path = options.path ?? "/callback";
        let instance;
        const server = createServer((request, response) => instance?.handle(request.url ?? "/", response));
        await new Promise((resolve, reject) => {
            server.once("error", reject);
            server.listen(options.port ?? 0, host, () => {
                server.off("error", reject);
                resolve();
            });
        });
        const address = server.address();
        if (!address || typeof address === "string")
            throw new Error("OAuth callback server did not bind to TCP");
        instance = new OAuthCallbackServer(server, `http://${redirectHost.includes(":") ? `[${redirectHost}]` : redirectHost}:${address.port}${path}`, [path, ...(options.extraPaths ?? [])], options.timeoutMs ?? 5 * 60_000, options.renderPage);
        return instance;
    }

waitForCallback(state, path) {
        if (this.pending.has(state))
            throw new Error("OAuth state is already pending");
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                this.pending.delete(state);
                reject(new Error("OAuth callback timed out"));
            }, this.timeoutMs);
            this.pending.set(state, { resolve, reject, timer, path });
        });
    }

async close() {
        for (const pending of this.pending.values()) {
            clearTimeout(pending.timer);
            pending.reject(new Error("OAuth callback server closed"));
        }
        this.pending.clear();
        await new Promise((resolve, reject) => {
            this.server.close((error) => (error ? reject(error) : resolve()));
        });
    }

reply(response, status, page) {
        if (this.renderPage) {
            response.writeHead(status, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
            response.end(this.renderPage(page));
        }
        else {
            response.writeHead(status, { "content-type": "text/plain; charset=utf-8" }).end(plainText(page));
        }
    }

handle(rawUrl, response) {
        const url = new URL(rawUrl, this.redirectUrl);
        if (!this.paths.includes(url.pathname)) {
            this.reply(response, 404, { ok: false, message: "Not found" });
            return;
        }
        const state = url.searchParams.get("state");
        const pending = state ? this.pending.get(state) : undefined;
        if (!state || !pending) {
            this.reply(response, 400, { ok: false, message: "Invalid or expired OAuth state" });
            return;
        }
        clearTimeout(pending.timer);
        this.pending.delete(state);
        if (pending.path !== undefined && url.pathname !== pending.path) {
            pending.reject(new Error("The authorization response arrived on another redirect URI"));
            this.reply(response, 400, { ok: false, message: "Unexpected redirect URI" });
            return;
        }
        const error = url.searchParams.get("error");
        if (error) {
            const description = url.searchParams.get("error_description") ?? error;
            pending.reject(new Error(description));
            this.reply(response, 200, {
                ok: false,
                message: "Authorization failed. You may close this window.",
                details: description,
            });
            return;
        }
        const code = url.searchParams.get("code");
        if (!code) {
            pending.reject(new Error("OAuth callback did not include an authorization code"));
            this.reply(response, 400, { ok: false, message: "Missing authorization code" });
            return;
        }
        const iss = url.searchParams.get("iss");
        pending.resolve({ code, state, ...(iss ? { iss } : {}) });
        this.reply(response, 200, { ok: true });
    }

function discard(response) {
    void response?.body?.cancel().catch(() => { });
}

function isDiscoveryMiss(status) {
    return (status >= 400 && status < 500) || status === 502;
}

function pathSuffix(pathname) {
    return pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;
}

function field(header, name) {
    const match = header.match(new RegExp(String.raw `(?:^|[,\s])${name}=(?:"([^"]*)"|([^\s,]+))`, "i"));
    // An empty value (`scope=""`) carries no information, so it counts as absent.
    return match?.[1] || match?.[2] || undefined;
}

export function parseWwwAuthenticate(header) {
    if (!header)
        return {};
    const scheme = header.trimStart().split(/\s+/, 1)[0]?.toLowerCase();
    if (scheme !== "bearer" && scheme !== "dpop")
        return {};
    const resourceMetadata = field(header, "resource_metadata");
    let resourceMetadataUrl;
    if (resourceMetadata) {
        try {
            resourceMetadataUrl = new URL(resourceMetadata);
        }
        catch { }
    }
    return {
        resourceMetadataUrl,
        scope: field(header, "scope"),
        error: field(header, "error"),
        errorDescription: field(header, "error_description"),
    };
}

async function fetchMetadata(url, fetch, protocolVersion, signal) {
    return fetch(url, {
        headers: { Accept: "application/json", "MCP-Protocol-Version": protocolVersion },
        signal,
    });
}

export async function discoverProtectedResourceMetadata(serverUrl, options = {}) {
    const server = new URL(serverUrl);
    const fetch = options.fetch ?? globalThis.fetch;
    const version = options.protocolVersion ?? LATEST_PROTOCOL_VERSION;
    let response = await fetchMetadata(options.resourceMetadataUrl
        ? new URL(options.resourceMetadataUrl)
        : new URL(`/.well-known/oauth-protected-resource${pathSuffix(server.pathname)}`, server.origin), fetch, version, options.signal);
    if (!options.resourceMetadataUrl && server.pathname !== "/" && isDiscoveryMiss(response.status)) {
        discard(response);
        response = await fetchMetadata(new URL("/.well-known/oauth-protected-resource", server.origin), fetch, version, options.signal);
    }
    if (!response.ok) {
        discard(response);
        throw new Error(`HTTP ${response.status} loading OAuth protected resource metadata`);
    }
    return parseProtectedResourceMetadata(await response.json());
}

export function buildAuthorizationServerDiscoveryUrls(authorizationServerUrl) {
    const issuer = new URL(authorizationServerUrl);
    const path = pathSuffix(issuer.pathname);
    const urls = [
        { url: new URL(`/.well-known/oauth-authorization-server${path}`, issuer.origin), type: "oauth" },
        { url: new URL(`/.well-known/openid-configuration${path}`, issuer.origin), type: "oidc" },
    ];
    if (path)
        urls.push({ url: new URL(`${path}/.well-known/openid-configuration`, issuer.origin), type: "oidc" });
    return urls;
}

export async function discoverAuthorizationServerMetadata(authorizationServerUrl, options = {}) {
    const fetch = options.fetch ?? globalThis.fetch;
    for (const { url } of buildAuthorizationServerDiscoveryUrls(authorizationServerUrl)) {
        const response = await fetchMetadata(url, fetch, options.protocolVersion ?? LATEST_PROTOCOL_VERSION, options.signal);
        if (!response.ok) {
            discard(response);
            if (isDiscoveryMiss(response.status))
                continue;
            throw new Error(`HTTP ${response.status} loading authorization server metadata from ${url}`);
        }
        const metadata = parseAuthorizationServerMetadata(await response.json());
        if (!options.skipIssuerValidation) {
            const expected = String(authorizationServerUrl);
            // URL parsing adds a trailing slash to bare origins, so compare without one on either side.
            const trim = (value) => (value.endsWith("/") ? value.slice(0, -1) : value);
            if (trim(metadata.issuer) !== trim(expected))
                throw new OAuthIssuerMismatchError(expected, metadata.issuer);
        }
        return metadata;
    }
    return undefined;
}

export async function discoverOAuthServerInfo(serverUrl, options = {}) {
    let resourceMetadata;
    try {
        resourceMetadata = await discoverProtectedResourceMetadata(serverUrl, {
            resourceMetadataUrl: options.resourceMetadataUrl,
            fetch: options.fetch,
            signal: options.signal,
        });
    }
    catch (error) {
        if (error instanceof TypeError)
            throw error;
    }
    if (options.authorizationServerMetadataUrl) {
        const url = options.authorizationServerMetadataUrl;
        const response = await fetchMetadata(url, options.fetch ?? globalThis.fetch, LATEST_PROTOCOL_VERSION, options.signal);
        if (!response.ok) {
            discard(response);
            throw new Error(`HTTP ${response.status} loading authorization server metadata from ${url}`);
        }
        const metadata = parseAuthorizationServerMetadata(await response.json());
        return { authorizationServerUrl: metadata.issuer, authorizationServerMetadata: metadata, resourceMetadata };
    }
    const authorizationServerUrl = resourceMetadata?.authorization_servers?.[0] ?? String(new URL("/", serverUrl));
    return {
        authorizationServerUrl,
        authorizationServerMetadata: await discoverAuthorizationServerMetadata(authorizationServerUrl, {
            fetch: options.fetch,
            skipIssuerValidation: options.skipIssuerValidation,
            signal: options.signal,
        }),
        resourceMetadata,
    };
}

export function resourceUrlFromServerUrl(value) {
    const url = new URL(value);
    url.hash = "";
    return url;
}

export function selectResource(serverUrl, metadata) {
    if (!metadata)
        return undefined;
    const requested = resourceUrlFromServerUrl(serverUrl);
    const configured = new URL(metadata.resource);
    if (requested.origin !== configured.origin) {
        throw new Error(`Protected resource ${metadata.resource} does not match MCP server ${requested}`);
    }
    const requestedPath = requested.pathname.endsWith("/") ? requested.pathname : `${requested.pathname}/`;
    const configuredPath = configured.pathname.endsWith("/") ? configured.pathname : `${configured.pathname}/`;
    if (!requestedPath.startsWith(configuredPath)) {
        throw new Error(`Protected resource ${metadata.resource} does not match MCP server ${requested}`);
    }
    return metadata.resource;
}

function loopback(hostname) {
    return hostname === "localhost" || hostname === "127.0.0.1" || hostname === "[::1]" || hostname === "::1";
}

function applicationType(redirectUris) {
    const native = redirectUris.some((uri) => {
        if (!URL.canParse(uri))
            return false;
        const url = new URL(uri);
        return (url.protocol !== "http:" && url.protocol !== "https:") || loopback(url.hostname);
    });
    return native ? "native" : "web";
}

function secureEndpoint(value) {
    const url = new URL(value);
    if (url.protocol !== "https:" && !loopback(url.hostname))
        throw new OAuthInsecureEndpointError(url.href);
    return url;
}

function selectClientAuthMethod(information, supported) {
    const hinted = "token_endpoint_auth_method" in information ? information.token_endpoint_auth_method : undefined;
    if (hinted &&
        ["client_secret_basic", "client_secret_post", "none"].includes(hinted) &&
        (supported.length === 0 || supported.includes(hinted))) {
        return hinted;
    }
    if (supported.length === 0)
        return information.client_secret ? "client_secret_basic" : "none";
    if (information.client_secret && supported.includes("client_secret_basic"))
        return "client_secret_basic";
    if (information.client_secret && supported.includes("client_secret_post"))
        return "client_secret_post";
    if (supported.includes("none"))
        return "none";
    return information.client_secret ? "client_secret_post" : "none";
}

function applyClientAuthentication(method, information, headers, params) {
    if (method === "client_secret_basic") {
        if (!information.client_secret)
            throw new Error("client_secret_basic requires a client secret");
        headers.set("Authorization", `Basic ${Buffer.from(`${information.client_id}:${information.client_secret}`).toString("base64")}`);
    }
    else {
        params.set("client_id", information.client_id);
        if (method === "client_secret_post" && information.client_secret)
            params.set("client_secret", information.client_secret);
    }
}

async function pkce() {
    const bytes = crypto.getRandomValues(new Uint8Array(32));
    const verifier = Buffer.from(bytes).toString("base64url");
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
    return { verifier, challenge: Buffer.from(digest).toString("base64url") };
}

export async function startAuthorization(authorizationServerUrl, options) {
    const metadata = options.metadata;
    if (metadata && !metadata.response_types_supported.includes("code")) {
        throw new Error("Authorization server does not support authorization codes");
    }
    if (metadata?.code_challenge_methods_supported && !metadata.code_challenge_methods_supported.includes("S256")) {
        throw new Error("Authorization server does not support PKCE S256");
    }
    const url = new URL(metadata?.authorization_endpoint ?? new URL("/authorize", authorizationServerUrl));
    const { verifier, challenge } = await pkce();
    url.searchParams.set("response_type", "code");
    url.searchParams.set("client_id", options.clientInformation.client_id);
    url.searchParams.set("code_challenge", challenge);
    url.searchParams.set("code_challenge_method", "S256");
    url.searchParams.set("redirect_uri", String(options.redirectUrl));
    if (options.state)
        url.searchParams.set("state", options.state);
    if (options.scope)
        url.searchParams.set("scope", options.scope);
    if (options.scope?.split(/\s+/).includes("offline_access"))
        url.searchParams.set("prompt", "consent");
    if (options.resource)
        url.searchParams.set("resource", options.resource);
    return { authorizationUrl: url, codeVerifier: verifier };
}

async function tokenRequest(authorizationServerUrl, options, params) {
    const url = secureEndpoint(options.metadata?.token_endpoint ?? new URL("/token", authorizationServerUrl));
    const headers = new Headers({ Accept: "application/json", "content-type": "application/x-www-form-urlencoded" });
    if (options.resource)
        params.set("resource", options.resource);
    if (options.addClientAuthentication) {
        await options.addClientAuthentication(headers, params, url, options.metadata);
    }
    else {
        applyClientAuthentication(selectClientAuthMethod(options.clientInformation, options.metadata?.token_endpoint_auth_methods_supported ?? []), options.clientInformation, headers, params);
    }
    const response = await (options.fetch ?? globalThis.fetch)(url, {
        method: "POST",
        headers,
        body: params,
        signal: options.signal,
    });
    const text = await response.text();
    let value;
    try {
        value = JSON.parse(text);
    }
    catch { }
    // Servers may report OAuth errors with any status, so check the body before the status.
    if (isObject(value) && typeof value.error === "string") {
        throw new OAuthError(value.error, typeof value.error_description === "string" ? value.error_description : value.error, typeof value.error_uri === "string" ? value.error_uri : undefined);
    }
    if (!response.ok)
        throw new OAuthError("server_error", `HTTP ${response.status}: ${text}`);
    return parseOAuthTokens(value);
}

export async function registerClient(authorizationServerUrl, options) {
    const endpoint = options.metadata?.registration_endpoint;
    if (options.metadata && !endpoint)
        throw new Error("Authorization server does not support dynamic client registration");
    const response = await (options.fetch ?? globalThis.fetch)(new URL(endpoint ?? new URL("/register", authorizationServerUrl)), {
        method: "POST",
        headers: { Accept: "application/json", "content-type": "application/json" },
        body: JSON.stringify({
            ...options.clientMetadata,
            application_type: options.clientMetadata.application_type ?? applicationType(options.clientMetadata.redirect_uris),
            ...(options.scope ? { scope: options.scope } : {}),
        }),
        signal: options.signal,
    });
    if (!response.ok)
        throw new OAuthRegistrationError(response.status, await response.text());
    return parseClientInformation(await response.json());
}

export async function exchangeAuthorizationCode(authorizationServerUrl, options) {
    return tokenRequest(authorizationServerUrl, options, new URLSearchParams({
        grant_type: "authorization_code",
        code: options.code,
        code_verifier: options.codeVerifier,
        redirect_uri: String(options.redirectUrl),
    }));
}

export async function refreshAuthorization(authorizationServerUrl, options) {
    const tokens = await tokenRequest(authorizationServerUrl, options, new URLSearchParams({ grant_type: "refresh_token", refresh_token: options.refreshToken }));
    return { refresh_token: options.refreshToken, ...tokens };
}

function withScope(tokens, scope) {
    return tokens.scope === undefined && scope ? { ...tokens, scope } : tokens;
}

export function stepUpScope(granted, challenged) {
    if (!challenged)
        return undefined;
    const scopes = [granted, challenged].flatMap((scope) => scope?.split(/\s+/).filter(Boolean) ?? []);
    return [...new Set(scopes)].join(" ");
}

async function runFlow(provider, options) {
    const metadataUrl = options.authorizationServerMetadataUrl && secureEndpoint(options.authorizationServerMetadataUrl);
    // With a configured metadata URL, discovery is not cached, so changing the URL applies at once.
    const cached = metadataUrl ? undefined : await provider.discoveryState?.();
    const discovered = cached?.authorizationServerUrl
        ? {
            authorizationServerUrl: cached.authorizationServerUrl,
            authorizationServerMetadata: cached.authorizationServerMetadata ??
                (await discoverAuthorizationServerMetadata(cached.authorizationServerUrl, {
                    fetch: options.fetch,
                    skipIssuerValidation: options.skipIssuerValidation,
                    signal: options.signal,
                })),
            resourceMetadata: cached.resourceMetadata,
        }
        : await discoverOAuthServerInfo(options.serverUrl, {
            resourceMetadataUrl: options.resourceMetadataUrl,
            authorizationServerMetadataUrl: metadataUrl,
            fetch: options.fetch,
            skipIssuerValidation: options.skipIssuerValidation,
            signal: options.signal,
        });
    if (!metadataUrl) {
        await provider.saveDiscoveryState?.({
            ...discovered,
            ...(options.resourceMetadataUrl ? { resourceMetadataUrl: options.resourceMetadataUrl.href } : {}),
        });
    }
    const metadata = discovered.authorizationServerMetadata;
    const resource = selectResource(options.serverUrl, discovered.resourceMetadata);
    // `||`, not `??`: an empty scope (for example from `scopes_supported: []`) falls through to the next source.
    const scope = options.scope || discovered.resourceMetadata?.scopes_supported?.join(" ") || provider.clientMetadata.scope;
    const stored = await provider.clientInformation();
    const clientDocument = stored ? undefined : provider.clientMetadataDocument?.(metadata);
    if (clientDocument) {
        const url = new URL(clientDocument.url);
        if (url.protocol !== "https:" || url.pathname === "/")
            throw new Error("Invalid OAuth client metadata URL");
    }
    let client = stored ?? (clientDocument && { client_id: clientDocument.url });
    if (!client) {
        if (options.authorizationCode)
            throw new Error("OAuth client information is missing during code exchange");
        if (!provider.saveClientInformation)
            throw new Error("OAuth client information cannot be persisted");
        client = await registerClient(discovered.authorizationServerUrl, {
            metadata,
            clientMetadata: provider.clientMetadata,
            scope,
            fetch: options.fetch,
            signal: options.signal,
        });
        await provider.saveClientInformation(client);
    }
    // The document's redirect URI may differ from the provider's, for example by a server-specific path.
    const redirectUrl = clientDocument?.redirectUrl ?? provider.redirectUrl;
    const tokenOptions = {
        metadata,
        clientInformation: client,
        resource,
        addClientAuthentication: provider.addClientAuthentication,
        fetch: options.fetch,
        signal: options.signal,
    };
    if (options.authorizationCode) {
        // RFC 9207: never send a code from another authorization server to this one. Without metadata there
        // is no issuer to compare with, so any `iss` is rejected.
        const iss = options.iss;
        if (iss !== undefined || metadata?.authorization_response_iss_parameter_supported) {
            if (iss !== metadata?.issuer)
                throw new OAuthIssuerMismatchError(metadata?.issuer, iss);
        }
        const tokens = await exchangeAuthorizationCode(discovered.authorizationServerUrl, {
            ...tokenOptions,
            code: options.authorizationCode,
            codeVerifier: await provider.codeVerifier(),
            redirectUrl,
        });
        // A response without `scope` grants the requested scope (RFC 6749 §5.1). Recorded so a step-up can
        // keep it. Callers pass the options of the authorization request, so `scope` is what was requested.
        await provider.saveTokens(withScope(tokens, scope));
        return "AUTHORIZED";
    }
    const existing = options.skipRefresh ? undefined : await provider.tokens();
    if (existing?.refresh_token) {
        try {
            const tokens = await refreshAuthorization(discovered.authorizationServerUrl, {
                ...tokenOptions,
                refreshToken: existing.refresh_token,
            });
            // A refresh without `scope` keeps the scope of the grant (RFC 6749 §6).
            await provider.saveTokens(withScope(tokens, existing.scope));
            return "AUTHORIZED";
        }
        catch (error) {
            if (options.signal?.aborted || error instanceof OAuthInsecureEndpointError)
                throw error;
            if (error instanceof OAuthError && error.code !== "server_error")
                throw error;
        }
    }
    const state = await provider.state?.();
    const authorization = await startAuthorization(discovered.authorizationServerUrl, {
        metadata,
        clientInformation: client,
        redirectUrl,
        scope,
        state,
        resource,
    });
    await provider.saveCodeVerifier(authorization.codeVerifier);
    await provider.redirectToAuthorization(authorization.authorizationUrl);
    return "REDIRECT";
}

export async function authorizeMcp(provider, options) {
    try {
        return await runFlow(provider, options);
    }
    catch (error) {
        if (error instanceof OAuthError && ["invalid_client", "unauthorized_client"].includes(error.code)) {
            await provider.invalidateCredentials?.("all");
            return runFlow(provider, options);
        }
        if (error instanceof OAuthError && error.code === "invalid_grant") {
            await provider.invalidateCredentials?.("tokens");
            return runFlow(provider, options);
        }
        throw error;
    }
}

export function adaptOAuthProvider(provider) {
    let inFlight;
    return {
        token: async () => (await provider.tokens())?.access_token,
        onUnauthorized: async (context) => {
            const challenge = parseWwwAuthenticate(context.response.headers.get("www-authenticate"));
            const insufficientScope = challenge.error === "insufficient_scope";
            if (!insufficientScope && !inFlight && context.token !== undefined) {
                const current = (await provider.tokens())?.access_token;
                if (current !== undefined && current !== context.token)
                    return;
            }
            inFlight ??= Promise.resolve(insufficientScope ? provider.tokens() : undefined)
                .then((granted) => authorizeMcp(provider, {
                serverUrl: context.serverUrl,
                resourceMetadataUrl: challenge.resourceMetadataUrl,
                scope: insufficientScope ? stepUpScope(granted?.scope, challenge.scope) : challenge.scope,
                fetch: context.fetch,
                skipRefresh: insufficientScope,
            }))
                .then((result) => {
                if (result === "REDIRECT")
                    throw new McpOAuthAuthorizationRequiredError();
            })
                .finally(() => {
                inFlight = undefined;
            });
            await inFlight;
        },
    };
}

load() {
        return this.value === undefined ? undefined : structuredClone(this.value);
    }

save(state) {
        this.value = structuredClone(state);
    }

async state() {
        const existing = (await this.load()).oauthState;
        if (existing)
            return existing;
        const state = Buffer.from(crypto.getRandomValues(new Uint8Array(32))).toString("hex");
        await this.update((value) => ({ ...value, oauthState: state }));
        return state;
    }

async clientInformation() {
        return this.configuredClient ?? (await this.load()).clientInformation;
    }

async saveClientInformation(information) {
        if (this.configuredClient)
            return;
        await this.update((value) => ({ ...value, clientInformation: information }));
    }

async tokens() {
        return (await this.load()).tokens;
    }

async saveTokens(tokens) {
        const expiresAt = tokens.expires_in === undefined ? undefined : Date.now() + tokens.expires_in * 1000;
        await this.update((value) => {
            const next = { ...value, tokens };
            if (expiresAt === undefined)
                delete next.tokensExpireAt;
            else
                next.tokensExpireAt = expiresAt;
            return next;
        });
    }

async redirectToAuthorization(url) {
        await this.onRedirect(url);
    }

async saveCodeVerifier(verifier) {
        await this.update((value) => ({ ...value, codeVerifier: verifier }));
    }

async codeVerifier() {
        const verifier = (await this.load()).codeVerifier;
        if (!verifier)
            throw new Error("No OAuth PKCE code verifier is stored");
        return verifier;
    }

async invalidateCredentials(kind) {
        await this.update((value) => {
            const next = { ...value };
            if (kind === "all" || kind === "client")
                delete next.clientInformation;
            if (kind === "all" || kind === "tokens") {
                delete next.tokens;
                delete next.tokensExpireAt;
            }
            if (kind === "all" || kind === "verifier")
                delete next.codeVerifier;
            if (kind === "all" || kind === "discovery")
                delete next.discovery;
            if (kind === "all")
                delete next.oauthState;
            return next;
        });
    }

async saveDiscoveryState(discovery) {
        await this.update((value) => ({ ...value, discovery }));
    }

async discoveryState() {
        return (await this.load()).discovery;
    }

async load() {
        await this.writes;
        return this.own(await this.store.load());
    }

async update(update) {
        this.writes = this.writes.then(async () => {
            await this.store.save(update(this.own(await this.store.load())));
        });
        await this.writes;
    }

own(state) {
        return state?.serverUrl === this.serverUrl ? state : { serverUrl: this.serverUrl };
    }

function object(value, name) {
    if (!isObject(value))
        throw new Error(`Invalid ${name}`);
    return value;
}

function compact(value) {
    return Object.fromEntries(Object.entries(value).filter(([, item]) => item !== undefined));
}

function requiredString(value, name) {
    if (typeof value !== "string" || value.length === 0)
        throw new Error(`Invalid ${name}`);
    return value;
}

function absent(value) {
    return value === undefined || value === null || value === "";
}

function optionalString(value, name) {
    if (absent(value))
        return undefined;
    return requiredString(value, name);
}

function optionalStrings(value, name) {
    if (value === undefined || value === null)
        return undefined;
    if (!Array.isArray(value) || value.some((item) => typeof item !== "string"))
        throw new Error(`Invalid ${name}`);
    return [...value];
}

function safeUrl(value, name) {
    const text = requiredString(value, name);
    // URL parsing throws a `TypeError`, which discovery reserves for network failures.
    if (!URL.canParse(text))
        throw new Error(`Invalid ${name}`);
    const url = new URL(text);
    if (["javascript:", "data:", "vbscript:"].includes(url.protocol))
        throw new Error(`Invalid ${name}`);
    return text;
}

function optionalUrl(value, name) {
    return absent(value) ? undefined : safeUrl(value, name);
}

export function parseProtectedResourceMetadata(value) {
    const input = object(value, "OAuth protected resource metadata");
    return compact({
        ...input,
        resource: safeUrl(input.resource, "OAuth protected resource metadata resource"),
        authorization_servers: optionalStrings(input.authorization_servers, "authorization_servers")?.map((url) => safeUrl(url, "authorization server URL")),
        scopes_supported: optionalStrings(input.scopes_supported, "scopes_supported"),
    });
}

export function parseAuthorizationServerMetadata(value) {
    const input = object(value, "authorization server metadata");
    const responseTypes = optionalStrings(input.response_types_supported, "response_types_supported");
    if (!responseTypes)
        throw new Error("Invalid response_types_supported");
    return compact({
        ...input,
        issuer: safeUrl(input.issuer, "authorization server issuer"),
        authorization_endpoint: safeUrl(input.authorization_endpoint, "authorization endpoint"),
        token_endpoint: safeUrl(input.token_endpoint, "token endpoint"),
        registration_endpoint: optionalUrl(input.registration_endpoint, "registration endpoint"),
        scopes_supported: optionalStrings(input.scopes_supported, "scopes_supported"),
        response_types_supported: responseTypes,
        grant_types_supported: optionalStrings(input.grant_types_supported, "grant_types_supported"),
        token_endpoint_auth_methods_supported: optionalStrings(input.token_endpoint_auth_methods_supported, "token_endpoint_auth_methods_supported"),
        code_challenge_methods_supported: optionalStrings(input.code_challenge_methods_supported, "code_challenge_methods_supported"),
        client_id_metadata_document_supported: typeof input.client_id_metadata_document_supported === "boolean"
            ? input.client_id_metadata_document_supported
            : undefined,
        authorization_response_iss_parameter_supported: typeof input.authorization_response_iss_parameter_supported === "boolean"
            ? input.authorization_response_iss_parameter_supported
            : undefined,
    });
}

export function parseOAuthTokens(value) {
    const input = object(value, "OAuth token response");
    // `Number(null)` is 0, which would mark the token as expired at once.
    const expires = absent(input.expires_in) ? undefined : Number(input.expires_in);
    if (expires !== undefined && !Number.isFinite(expires))
        throw new Error("Invalid expires_in");
    return compact({
        access_token: requiredString(input.access_token, "access_token"),
        token_type: requiredString(input.token_type, "token_type"),
        expires_in: expires,
        scope: optionalString(input.scope, "scope"),
        refresh_token: optionalString(input.refresh_token, "refresh_token"),
        id_token: optionalString(input.id_token, "id_token"),
    });
}

export function parseClientInformation(value) {
    const input = object(value, "OAuth client registration response");
    return compact({
        ...input,
        client_id: requiredString(input.client_id, "client_id"),
        client_secret: optionalString(input.client_secret, "client_secret"),
        client_id_issued_at: typeof input.client_id_issued_at === "number" ? input.client_id_issued_at : undefined,
        client_secret_expires_at: typeof input.client_secret_expires_at === "number" ? input.client_secret_expires_at : undefined,
        redirect_uris: optionalStrings(input.redirect_uris, "redirect_uris") ?? [],
    });
}

function blockToLlmContent(block) {
    switch (block.type) {
        case "text":
            return { type: "text", text: block.text };
        case "image":
            return { type: "image", data: block.data, mimeType: block.mimeType };
        case "audio":
            return { type: "text", text: `[audio ${block.mimeType} omitted]` };
        case "resource_link":
            return { type: "text", text: `${block.name}: ${block.uri}` };
        case "resource": {
            const resource = block.resource;
            if ("text" in resource)
                return { type: "text", text: resource.text };
            if (resource.mimeType?.startsWith("image/")) {
                return { type: "image", data: resource.blob, mimeType: resource.mimeType };
            }
            return {
                type: "text",
                text: `[binary resource ${resource.uri} (${resource.mimeType ?? "unknown type"}) omitted]`,
            };
        }
        default:
            return { type: "text", text: `[unsupported MCP content ${block.type}]` };
    }
}

export function toLlmContent(result) {
    const content = (result.content ?? []).map(blockToLlmContent);
    if (content.length === 0 && result.structuredContent !== undefined) {
        content.push({ type: "text", text: JSON.stringify(result.structuredContent, null, 2) });
    }
    return content;
}

export function isObject(value) {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function toError(value) {
    return value instanceof Error ? value : new Error(String(value));
}

export function isJsonRpcId(value) {
    return typeof value === "string" || (typeof value === "number" && Number.isFinite(value));
}

export function isJsonRpcRequest(message) {
    return (isObject(message) && message.jsonrpc === "2.0" && isJsonRpcId(message.id) && typeof message.method === "string");
}

export function isJsonRpcNotification(message) {
    return isObject(message) && message.jsonrpc === "2.0" && !("id" in message) && typeof message.method === "string";
}

export function isJsonRpcResponse(message) {
    if (!isObject(message) || message.jsonrpc !== "2.0" || !isJsonRpcId(message.id))
        return false;
    if ("result" in message)
        return !("error" in message);
    if (!("error" in message) || !isObject(message.error))
        return false;
    return typeof message.error.code === "number" && typeof message.error.message === "string";
}

export function parseJsonRpcMessage(value) {
    if (isJsonRpcRequest(value) || isJsonRpcNotification(value) || isJsonRpcResponse(value))
        return value;
    throw new McpError(JSON_RPC_ERROR_CODES.invalidRequest, "Invalid JSON-RPC message");
}

connectPeer(peer) {
        if (this.peer)
            throw new Error("In-memory MCP transport already has a peer");
        this.peer = peer;
    }

async start() {
        if (this.closed)
            throw new McpConnectionClosedError();
        this.started = true;
    }

async send(message) {
        if (!this.started || this.closed)
            throw new McpConnectionClosedError();
        const peer = this.peer;
        if (!peer?.started || peer.closed)
            throw new McpConnectionClosedError("In-memory MCP peer is not connected");
        const copy = structuredClone(message);
        queueMicrotask(() => peer.deliver(copy));
    }

async close() {
        if (this.closed)
            return;
        this.closed = true;
        this.emitClose();
        await this.peer?.close();
    }

emitError(error) {
        super.emitError(error);
    }

deliver(message) {
        if (this.closed)
            return;
        this.emitMessage(message);
    }

export function createInMemoryTransportPair() {
    const client = new InMemoryTransport();
    const server = new InMemoryTransport();
    client.connectPeer(server);
    server.connectPeer(client);
    return { client, server };
}

function killProcessTree(child, signal) {
    const pid = child.pid;
    if (process.platform === "win32" && pid !== undefined) {
        if (child.exitCode !== null)
            return;
        // Windows has no graceful signals, and cross-spawn runs `.cmd` shims through cmd.exe; killing only
        // that would leave the server running.
        spawn("taskkill", ["/pid", String(pid), "/T", "/F"], { stdio: "ignore", windowsHide: true }).on("error", () => { });
        return;
    }
    if (USE_PROCESS_GROUPS && pid !== undefined) {
        try {
            // Negative pid: the whole group, so wrappers like `npx` or `uvx` do not leave the server behind.
            process.kill(-pid, signal);
            return;
        }
        catch {
            // The group is gone or was never created; fall back to the direct child.
        }
    }
    try {
        child.kill(signal);
    }
    catch { }
}

function installExitHook() {
    if (exitHookInstalled)
        return;
    exitHookInstalled = true;
    process.once("exit", () => {
        for (const pid of liveProcessGroups) {
            try {
                process.kill(-pid, "SIGTERM");
            }
            catch { }
        }
    });
}

get pid() {
        return this.child?.pid;
    }

get stderr() {
        return this.stderrBuffer.toString("utf8");
    }

async start() {
        if (this.started)
            throw new Error("MCP stdio transport already started");
        if (this.closed)
            throw new McpConnectionClosedError();
        this.started = true;
        const env = this.options.inheritEnv === false ? { ...this.options.env } : { ...process.env, ...this.options.env };
        const child = crossSpawn(this.options.command, this.options.args ?? [], {
            cwd: this.options.cwd,
            env,
            stdio: ["pipe", "pipe", this.options.stderr === "inherit" ? "inherit" : "pipe"],
            windowsHide: true,
            // Own process group, so closing the transport can terminate the server's children too.
            detached: USE_PROCESS_GROUPS,
        });
        this.child = child;
        const pid = child.pid;
        if (USE_PROCESS_GROUPS && pid !== undefined) {
            installExitHook();
            liveProcessGroups.add(pid);
            child.once("exit", () => liveProcessGroups.delete(pid));
        }
        child.stdout?.on("data", (chunk) => this.handleStdout(chunk));
        child.stdout?.on("error", (error) => this.emitError(error));
        child.stdin?.on("error", (error) => {
            if (!this.closed)
                this.emitError(error);
        });
        child.stderr?.on("data", (chunk) => this.handleStderr(chunk));
        child.stderr?.on("error", (error) => this.emitError(error));
        child.on("close", () => {
            this.child = undefined;
            if (this.stdoutBuffer.toString("utf8").trim()) {
                this.emitError(new Error("MCP stdio server closed with an incomplete JSON-RPC message"));
            }
            this.stdoutBuffer = Buffer.alloc(0);
            this.emitClose();
        });
        await new Promise((resolve, reject) => {
            const onSpawn = () => {
                child.off("error", onError);
                resolve();
            };
            const onError = (error) => {
                child.off("spawn", onSpawn);
                reject(error);
            };
            child.once("spawn", onSpawn);
            child.once("error", onError);
        });
        child.on("error", (error) => {
            if (!this.closed)
                this.emitError(error);
        });
    }

async send(message) {
        const stdin = this.child?.stdin;
        if (!this.started || this.closed || !stdin?.writable)
            throw new McpConnectionClosedError();
        const payload = `${JSON.stringify(message)}\n`;
        await new Promise((resolve, reject) => {
            stdin.write(payload, (error) => (error ? reject(error) : resolve()));
        });
    }

async close() {
        if (this.closed)
            return;
        this.closed = true;
        const child = this.child;
        if (!child) {
            this.emitClose();
            return;
        }
        if (child.exitCode !== null || child.signalCode !== null) {
            child.stdin?.end();
            return;
        }
        // Shutdown per the spec: close stdin and let the server exit, then SIGTERM, then SIGKILL.
        const closeTimeoutMs = this.options.closeTimeoutMs ?? DEFAULT_CLOSE_TIMEOUT_MS;
        await new Promise((resolve) => {
            const timers = [];
            child.once("close", () => {
                for (const timer of timers)
                    clearTimeout(timer);
                // Children of the server that ignored stdin closing would otherwise outlive it.
                killProcessTree(child, "SIGTERM");
                resolve();
            });
            const grace = Math.min(STDIN_CLOSE_GRACE_MS, closeTimeoutMs);
            timers.push(setTimeout(() => killProcessTree(child, "SIGTERM"), grace));
            timers.push(setTimeout(() => killProcessTree(child, "SIGKILL"), grace + closeTimeoutMs));
            child.stdin?.end();
        });
    }

handleStdout(chunk) {
        this.stdoutBuffer = Buffer.concat([this.stdoutBuffer, Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)]);
        const maxMessageBytes = this.options.maxMessageBytes ?? DEFAULT_MAX_MESSAGE_BYTES;
        while (true) {
            const newline = this.stdoutBuffer.indexOf(0x0a);
            if (newline < 0) {
                if (this.stdoutBuffer.length > maxMessageBytes) {
                    this.stdoutBuffer = Buffer.alloc(0);
                    this.emitError(new Error(`MCP stdio message exceeds ${maxMessageBytes} bytes`));
                }
                return;
            }
            const line = this.stdoutBuffer.subarray(0, newline);
            this.stdoutBuffer = this.stdoutBuffer.subarray(newline + 1);
            if (line.length > maxMessageBytes) {
                this.emitError(new Error(`MCP stdio message exceeds ${maxMessageBytes} bytes`));
                continue;
            }
            const text = line.toString("utf8").replace(/\r$/, "");
            if (!text.trim())
                continue;
            try {
                this.emitMessage(parseJsonRpcMessage(JSON.parse(text)));
            }
            catch (error) {
                this.emitError(error);
            }
        }
    }

handleStderr(chunk) {
        const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
        const maxStderrBytes = this.options.maxStderrBytes ?? DEFAULT_MAX_STDERR_BYTES;
        this.stderrBuffer = Buffer.concat([this.stderrBuffer, buffer]);
        if (this.stderrBuffer.length > maxStderrBytes)
            this.stderrBuffer = this.stderrBuffer.subarray(-maxStderrBytes);
        this.options.onStderr?.(buffer.toString("utf8"));
    }

export async function consumeSseStream(stream, options) {
    const reader = stream.getReader();
    const decoder = new TextDecoder();
    let buffered = "";
    let eventName;
    let eventId;
    let dataLines = [];
    // Bytes of the pending event's data, including the "\n" joins, so events streamed as many
    // short `data:` lines without a terminating blank line cannot grow without bound.
    let dataBytes = 0;
    const maxEventBytes = options.maxEventBytes ?? DEFAULT_MAX_MESSAGE_BYTES;
    const dispatch = () => {
        if (dataLines.length === 0) {
            eventName = undefined;
            eventId = undefined;
            return;
        }
        const data = dataLines.join("\n");
        options.onEvent({ ...(eventName ? { event: eventName } : {}), data, ...(eventId ? { id: eventId } : {}) });
        eventName = undefined;
        eventId = undefined;
        dataLines = [];
        dataBytes = 0;
    };
    const processLine = (rawLine) => {
        const line = rawLine.endsWith("\r") ? rawLine.slice(0, -1) : rawLine;
        if (line === "") {
            dispatch();
            return;
        }
        if (line.startsWith(":"))
            return;
        const colon = line.indexOf(":");
        const field = colon < 0 ? line : line.slice(0, colon);
        let value = colon < 0 ? "" : line.slice(colon + 1);
        if (value.startsWith(" "))
            value = value.slice(1);
        if (field === "data") {
            dataBytes += Buffer.byteLength(value) + (dataLines.length > 0 ? 1 : 0);
            if (dataBytes > maxEventBytes)
                throw new Error(`MCP SSE event exceeds ${maxEventBytes} bytes`);
            dataLines.push(value);
        }
        else if (field === "event")
            eventName = value;
        else if (field === "id" && !value.includes("\0")) {
            eventId = value;
            options.onId?.(value);
        }
        else if (field === "retry" && /^\d+$/.test(value))
            options.onRetry?.(Number(value));
    };
    try {
        while (true) {
            const { done, value } = await reader.read();
            if (done)
                break;
            buffered += decoder.decode(value, { stream: true });
            let newline = buffered.indexOf("\n");
            while (newline >= 0) {
                processLine(buffered.slice(0, newline));
                buffered = buffered.slice(newline + 1);
                newline = buffered.indexOf("\n");
            }
            if (Buffer.byteLength(buffered) > maxEventBytes)
                throw new Error(`MCP SSE event exceeds ${maxEventBytes} bytes`);
        }
        buffered += decoder.decode();
        if (buffered)
            processLine(buffered);
        dispatch();
    }
    finally {
        reader.releaseLock();
    }
}

function contentType(response) {
    return response.headers.get("content-type")?.split(";", 1)[0]?.trim().toLowerCase();
}

function needsAuthorization(response) {
    if (response.status === 401)
        return true;
    if (response.status !== 403)
        return false;
    return /(?:^|[\s,])error="?insufficient_scope"?/i.test(response.headers.get("www-authenticate") ?? "");
}

function isTransientStatus(status) {
    return status === 408 || status === 429 || status >= 500;
}

function discard(response) {
    return response.body?.cancel().catch(() => { }) ?? Promise.resolve();
}

function describeHttpFailure(status, body) {
    const text = body.trim();
    const snippet = text.length > ERROR_MESSAGE_BODY_CHARS ? `${text.slice(0, ERROR_MESSAGE_BODY_CHARS - 3)}...` : text;
    return `MCP HTTP request failed with status ${status}${snippet ? `: ${snippet}` : ""}`;
}

get sessionId() {
        return this.sessionIdValue;
    }

async start() {
        if (this.started)
            throw new Error("MCP Streamable HTTP transport already started");
        if (this.closed)
            throw new McpConnectionClosedError();
        this.started = true;
    }

setProtocolVersion(version) {
        this.protocolVersion = version;
    }

async send(message, { signal } = {}) {
        if (!this.started || this.closed)
            throw new McpConnectionClosedError();
        const response = await this.authorizedFetch("POST", {
            headers: { accept: "application/json, text/event-stream", "content-type": "application/json" },
            body: JSON.stringify(message),
        }, signal);
        await this.checkResponse(response);
        this.captureSession(response);
        if (!isJsonRpcRequest(message)) {
            // Notifications and responses are acknowledged with 202 and carry no reply; ignore any body.
            await discard(response);
            // The server-to-client stream may only open once the session is initialized.
            if ("method" in message && message.method === "notifications/initialized")
                this.startGetStream();
            return;
        }
        if (response.status === 202 || response.status === 204) {
            throw new McpHttpError(response.status, `MCP server accepted request ${message.method} without a response`);
        }
        const type = contentType(response);
        if (type === "application/json") {
            const body = await response.json();
            for (const item of Array.isArray(body) ? body : [body])
                this.emitMessage(parseJsonRpcMessage(item));
            return;
        }
        if (type === "text/event-stream" && response.body) {
            void this.consumeResponseStream(response.body, message.id);
            return;
        }
        await discard(response);
        throw new McpHttpError(response.status, `Unsupported MCP response content type: ${type ?? "missing"}`);
    }

async close() {
        if (this.closed)
            return;
        this.closed = true;
        this.controller.abort();
        if (this.started && this.sessionIdValue) {
            // Best effort: the session expires on the server anyway. The auth provider may refresh tokens
            // over the network, so it is not asked here and closing never waits for a refresh.
            try {
                const response = await this.fetch(this.url, {
                    method: "DELETE",
                    headers: this.buildHeaders({}, this.lastToken),
                    signal: AbortSignal.timeout(1_000),
                });
                await discard(response);
            }
            catch { }
        }
        this.emitClose();
    }

async authorizedFetch(method, init, signal) {
        const onUnauthorized = this.options.authProvider?.onUnauthorized?.bind(this.options.authProvider);
        for (let attempt = 0;; attempt++) {
            const { headers, token } = await this.headers(init.headers);
            if (signal?.aborted)
                throw new McpAbortError();
            const response = await this.fetch(this.url, {
                method,
                headers,
                body: init.body,
                signal: this.controller.signal,
            });
            if (attempt > 0 || !onUnauthorized || !needsAuthorization(response))
                return response;
            try {
                await onUnauthorized({ response, serverUrl: this.url, fetch: this.fetch, token });
            }
            finally {
                await discard(response);
            }
        }
    }

async headers(extra = {}) {
        const token = await this.options.authProvider?.token();
        this.lastToken = token;
        return { headers: this.buildHeaders(extra, token), ...(token ? { token } : {}) };
    }

buildHeaders(extra, token) {
        const headers = new Headers(this.options.headers);
        for (const [name, value] of Object.entries(extra))
            headers.set(name, value);
        if (this.sessionIdValue)
            headers.set("Mcp-Session-Id", this.sessionIdValue);
        if (this.protocolVersion)
            headers.set("MCP-Protocol-Version", this.protocolVersion);
        if (token)
            headers.set("Authorization", `Bearer ${token}`);
        return headers;
    }

captureSession(response) {
        const sessionId = response.headers.get("mcp-session-id");
        if (sessionId)
            this.sessionIdValue = sessionId;
    }

async checkResponse(response) {
        if (response.ok)
            return;
        const body = (await response.text().catch(() => "")).slice(0, MAX_ERROR_BODY_BYTES);
        if (response.status === 401)
            throw new McpAuthRequiredError(response, body);
        if (response.status === 404 && this.sessionIdValue)
            throw new McpSessionExpiredError(body);
        throw new McpHttpError(response.status, describeHttpFailure(response.status, body), body);
    }

async consumeSse(stream, cursor, onMessage) {
        await consumeSseStream(stream, {
            maxEventBytes: this.options.maxMessageBytes ?? DEFAULT_MAX_MESSAGE_BYTES,
            onId: (id) => {
                cursor.lastEventId = id;
            },
            onRetry: (delayMs) => {
                cursor.retryMs = delayMs;
            },
            onEvent: (event) => {
                cursor.received = true;
                // Events without data prime resumption; other event types are not JSON-RPC.
                if (!event.data.trim() || (event.event !== undefined && event.event !== "message"))
                    return;
                let message;
                try {
                    message = parseJsonRpcMessage(JSON.parse(event.data));
                }
                catch (error) {
                    this.emitError(error);
                    return;
                }
                onMessage?.(message);
                this.emitMessage(message);
            },
        });
    }

async consumeResponseStream(body, requestId) {
